TWComponent.script:
try{
	var inputList = new tw.object.listOf.String();
	inputList = tw.local.data.split(",");
	tw.local.collateralAmnt = inputList[0];
	tw.local.defaultPercentage = inputList[1];
}catch (err) {
	tw.local.errorMSG = err.message;
	throw new Error(tw.local.errorMSG);
	
}

